import{_ as t,o,c as r,ag as a}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"source":"resources/troubleshooting.md"},"headers":[],"relativePath":"resources/troubleshooting.md","filePath":"resources/troubleshooting.md"}'),s={name:"resources/troubleshooting.md"};function i(n,e,l,d,h,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><blockquote><p>Something broke. Find it below, work through the steps in order, and stop when it&#39;s fixed. Limits and which tool is the fallback are in <a href="./../TOOLS.html">Tool Handout</a>; this page says what to <em>do</em>.</p></blockquote><p><strong>Jump to:</strong> <a href="#my-api-call-fails-401-404-429">API errors</a> · <a href="#request-too-large-or-the-context-is-full">Request too large</a> · <a href="#i-ran-out-of-a-free-allowance">Out of allowance</a> · <a href="#the-local-model-ignores-its-tools">Local model ignores tools</a> · <a href="#the-lab-machine-is-slow-or-unreachable">Lab machine</a> · <a href="#my-codespace-wont-start-or-im-out-of-hours">Codespaces</a> · <a href="#the-class-codebase-wont-build">Class codebase won&#39;t build</a> · <a href="#git-worktrees">Worktrees</a> · <a href="#ci-minutes-and-failing-workflows">CI</a> · <a href="#mcp-the-server-wont-connect">MCP</a> · <a href="#the-agent-broke-or-deleted-things">Agent damage</a> · <a href="#i-committed-a-secret">Committed a secret</a> · <a href="#still-stuck">Still stuck</a></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Before anything else: what did you expect, what happened instead (the <strong>exact</strong> error text), and what changed since it last worked? Write the three answers down. They solve many problems on their own, and they are the first thing staff will ask.</p></div><p>Running out of a free allowance is not a reason to be late. Switching to the fallback is part of the course, and so is logging the switch in <code>AI_LOG.md</code>.</p><hr><h2 id="my-api-call-fails-401-404-429" tabindex="-1">My API call fails (401, 404, 429) <a class="header-anchor" href="#my-api-call-fails-401-404-429" aria-label="Permalink to &quot;My API call fails (401, 404, 429)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Usually means</th><th>Do this</th></tr></thead><tbody><tr><td><strong>401</strong> or <strong>403</strong></td><td>Wrong, revoked or missing key; or the key is for a different provider than <code>LLM_BASE_URL</code></td><td>Check the variable is set without printing it: <code>test -n &quot;$LLM_API_KEY&quot; &amp;&amp; echo set</code>. Check <code>.env</code> and Codespaces secrets don&#39;t both set it. Make a new key if in doubt</td></tr><tr><td><strong>404</strong></td><td>Wrong base URL (often a missing or doubled <code>/v1</code> or trailing slash) or a model ID the provider doesn&#39;t serve</td><td>Compare <code>LLM_BASE_URL</code> and <code>LLM_MODEL</code> with <a href="./../TOOLS.html#llm-apis-for-the-kits">Tool Handout: LLM APIs for the kits</a> character by character. List the models your key can use: <code>curl -s &quot;${LLM_BASE_URL%/}/models&quot; -H &quot;Authorization: Bearer $LLM_API_KEY&quot;</code></td></tr><tr><td><strong>400</strong></td><td>The request is malformed: often a tool schema the provider rejects, or a parameter it doesn&#39;t support</td><td>Read the error body; it usually names the field. Try the <a href="./../setup/local-models.html#the-tool-calling-smoke-test">smoke test</a> against the same provider</td></tr><tr><td><strong>429</strong></td><td>Rate limit: requests or tokens per minute, or a daily cap</td><td>Wait and retry with exponential backoff (<code>mini-agent</code> does this). If it persists, you&#39;ve hit a daily cap: switch provider by configuration (<a href="./../setup/api-keys.html#switching-provider-or-using-the-lab-machine">api-keys</a>)</td></tr><tr><td><strong>5xx</strong></td><td>The provider is having a bad day</td><td>Retry later, or switch provider</td></tr></tbody></table><h2 id="request-too-large-or-the-context-is-full" tabindex="-1">&quot;Request too large&quot;, or the context is full <a class="header-anchor" href="#request-too-large-or-the-context-is-full" aria-label="Permalink to &quot;&quot;Request too large&quot;, or the context is full&quot;">​</a></h2><p>Some free tiers cap tokens <strong>per minute</strong> below the size of one agent turn (system prompt + tool schemas + file contents). The request is rejected however long you wait.</p><ol><li>Use that provider only for the kits, whose prompts are lean, not for an IDE or CLI agent (<a href="./../TOOLS.html#spreading-the-work-across-free-allowances">Tool Handout: Spreading the work across free allowances</a>).</li><li>In <code>mini-agent</code>: read file ranges instead of whole files, trim tool output before returning it, and compact or drop old turns (a week 2 extension).</li><li>For a CLI agent: start a fresh session, give it fewer files, or move to a provider with a larger allowance.</li></ol><h2 id="i-ran-out-of-a-free-allowance" tabindex="-1">I ran out of a free allowance <a class="header-anchor" href="#i-ran-out-of-a-free-allowance" aria-label="Permalink to &quot;I ran out of a free allowance&quot;">​</a></h2><ol><li><strong>Switch now</strong>, to the next tool in the <a href="./../TOOLS.html#the-stack-at-a-glance">stack table</a>, and note it in <code>AI_LOG.md</code>. Don&#39;t add a payment method (<a href="./../setup/safety-contract.html#6-spending-caps-at-zero">rule 6</a>).</li><li><strong>Copilot credits gone?</strong> Completions still work. Move agent work to your Gemini key, the lab machine or Zed Student until the 1st of the month.</li><li><strong>Codespaces hours gone?</strong> Use a dev container on your laptop (<a href="./../setup/sandboxes.html#dev-containers-on-your-laptop">sandboxes</a>), or pair with a teammate.</li><li><strong>Spend less per task next time:</strong> smaller tasks, fresh sessions, Ask mode for questions, and the lab machine for anything repetitive (eval runs, batch jobs).</li><li>Tell staff if it happens before mid-month: it may mean a lab assumes more capacity than the free tiers give, and TOOLS.md needs fixing.</li></ol><h2 id="the-local-model-ignores-its-tools" tabindex="-1">The local model ignores its tools <a class="header-anchor" href="#the-local-model-ignores-its-tools" aria-label="Permalink to &quot;The local model ignores its tools&quot;">​</a></h2><p>Symptoms: the model answers in prose, prints a shell command as text, or the agent loop ends after one turn with no tool call.</p><ol><li><strong>The context is too small</strong> (the usual cause). Ollama truncates long prompts silently, cutting the tool definitions. Restart the server with <code>OLLAMA_CONTEXT_LENGTH=64000</code> (<a href="./../setup/local-models.html#the-64k-context-setting-and-why-tool-calls-fail-silently-without-it">local models</a>) and run the smoke test with padding.</li><li><strong>The model can&#39;t do tool calls reliably.</strong> If the unpadded smoke test also fails, try the next model in TOOLS.md. Tool-calling skill depends on training more than size.</li><li><strong>The harness&#39;s system prompt is too big</strong> for the context you set. Full IDE and CLI agents send far more than <code>mini-agent</code>; use a free API for those.</li><li><strong>Everything is slow:</strong> the model plus its context doesn&#39;t fit in GPU memory, so it spilled to the CPU. Use a smaller model, not a smaller context.</li></ol><h2 id="the-lab-machine-is-slow-or-unreachable" tabindex="-1">The lab machine is slow or unreachable <a class="header-anchor" href="#the-lab-machine-is-slow-or-unreachable" aria-label="Permalink to &quot;The lab machine is slow or unreachable&quot;">​</a></h2><ul><li><strong><code>connection refused</code> or a timeout:</strong> are you on the campus network or VPN, or using the authenticated endpoint your instructor gave you? A Codespace is outside the campus network.</li><li><strong>Very slow:</strong> it&#39;s one queue for the class. Check the class channel for a batch in progress, run your work later, or switch to a free API by configuration.</li><li><strong>Errors under load:</strong> keep your step limit and timeout on; retry with backoff; never leave a loop running unattended.</li><li><strong>It&#39;s down:</strong> that&#39;s the planned fallback drill. Switch provider and tell staff.</li></ul><h2 id="my-codespace-wont-start-or-im-out-of-hours" tabindex="-1">My Codespace won&#39;t start, or I&#39;m out of hours <a class="header-anchor" href="#my-codespace-wont-start-or-im-out-of-hours" aria-label="Permalink to &quot;My Codespace won&#39;t start, or I&#39;m out of hours&quot;">​</a></h2><ol><li>Check <a href="https://www.githubstatus.com/" target="_blank" rel="noreferrer">githubstatus.com</a>.</li><li>Out of hours? Codespaces are blocked, not billed, without a payment method. Stop and delete codespaces you aren&#39;t using (github.com/codespaces), and use the smallest machine that works.</li><li>Won&#39;t start: try a private browser window, or pause extensions that block <code>github.dev</code> and <code>*.app.github.dev</code>.</li><li>Stuck building: open the creation log (<strong>View creation log</strong>) and read the last error. A failing <code>postCreateCommand</code> in <code>devcontainer.json</code> is the usual cause.</li><li>Meanwhile, use a dev container on your laptop, or github.dev (press <code>.</code> on the repository page) for reading and small edits.</li></ol><h2 id="the-class-codebase-wont-build" tabindex="-1">The class codebase won&#39;t build <a class="header-anchor" href="#the-class-codebase-wont-build" aria-label="Permalink to &quot;The class codebase won&#39;t build&quot;">​</a></h2><ol><li>Follow <a href="./../project/class-codebase.html">The Class Codebase</a> exactly, in a fresh codespace, before improvising.</li><li>Check the runtime version it needs against <code>node --version</code> / <code>python3 --version</code>. The course standardizes on the versions in <a href="./../TOOLS.html#free-infrastructure">Tool Handout: Free infrastructure</a>.</li><li>Too slow or out of memory on 2 cores? Try 4 cores for the build only (it uses hours twice as fast), then go back.</li><li>Ask your team: someone may already have hit it. Post the exact error in the team channel, then to staff.</li><li>Don&#39;t let an agent &quot;fix&quot; the build by editing lockfiles, CI config or dependency versions without a plan you&#39;ve approved.</li></ol><h2 id="git-worktrees" tabindex="-1">Git worktrees <a class="header-anchor" href="#git-worktrees" aria-label="Permalink to &quot;Git worktrees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Fix</th></tr></thead><tbody><tr><td><code>fatal: &#39;[branch]&#39; is already checked out at …</code></td><td>A branch can be checked out in only one worktree. Create a new branch: <code>git worktree add ../dir -b new-branch</code></td></tr><tr><td><code>npm test</code> fails in the new worktree but works in the main one</td><td>Each worktree has its own working files: run <code>npm install</code> there</td></tr><tr><td>Two servers fight over a port</td><td>Give each worktree its own port (an environment variable or a command-line flag)</td></tr><tr><td>A deleted worktree directory still shows in <code>git worktree list</code></td><td><code>git worktree prune</code></td></tr><tr><td>Removing a worktree with uncommitted work</td><td><code>git worktree remove</code> refuses; commit or stash first, or check what you&#39;d lose before adding <code>--force</code></td></tr><tr><td>Agents in two worktrees edited the same file</td><td>A merge conflict you scheduled. Resolve it yourself, at the merge point you named (<a href="./agent-patterns.html#worktrees">agent patterns</a>)</td></tr></tbody></table><p>Never let an agent run <code>git worktree remove --force</code>, <code>git reset --hard</code> or <code>git clean -fdx</code> without your approval.</p><h2 id="ci-minutes-and-failing-workflows" tabindex="-1">CI minutes and failing workflows <a class="header-anchor" href="#ci-minutes-and-failing-workflows" aria-label="Permalink to &quot;CI minutes and failing workflows&quot;">​</a></h2><ul><li><strong>Minutes running out?</strong> Standard runners are free on public repositories; your team fork is public, so check that the workflow runs there and not on a private copy. Larger runners are billed even on public repositories: use the standard ones.</li><li><strong>Cut waste:</strong> add <code>concurrency</code> with <code>cancel-in-progress: true</code> so a new push cancels the old run; use <code>paths</code> filters so docs-only changes skip the test job; cache dependencies.</li><li><strong>A workflow from a fork has no secrets:</strong> that&#39;s intended. Never &quot;fix&quot; it by using <code>pull_request_target</code> with a checkout of the fork&#39;s code.</li><li><strong>CodeQL or Semgrep fails the build:</strong> read the finding before you suppress it. A suppression needs a comment saying why, and a reviewer.</li><li><strong>Self-hosted runner on a lab machine:</strong> trusted repositories only, never pull requests from forks.</li><li><strong>An agentic workflow or AI reviewer ran up usage:</strong> check its per-run cap first (<a href="./../setup/safety-contract.html#6-spending-caps-at-zero">rule 6</a>), then disable it until it&#39;s lowered.</li></ul><h2 id="mcp-the-server-wont-connect" tabindex="-1">MCP: the server won&#39;t connect <a class="header-anchor" href="#mcp-the-server-wont-connect" aria-label="Permalink to &quot;MCP: the server won&#39;t connect&quot;">​</a></h2><ol><li><strong>Run the server by hand</strong> from the exact command and working directory the client uses. Does it start? Does it exit with an error?</li><li><strong>Nothing may go to stdout but protocol messages.</strong> Over stdio, each line on stdout must be one JSON-RPC message. A stray <code>console.log</code> or a startup banner breaks the connection; log to stderr instead.</li><li><strong>Paths.</strong> Clients often launch servers from a different working directory. Use absolute paths in the client&#39;s config, or resolve paths relative to the server file.</li><li><strong>Exercise it with MCP Inspector</strong> (<code>npx @modelcontextprotocol/inspector [command]</code>) or the kit&#39;s own client script, to separate server bugs from client bugs.</li><li><strong>Protocol versions.</strong> The specification changes, and newer clients may skip the <code>initialize</code> handshake that older servers expect, or send the version differently (<a href="./../TOOLS.html#free-infrastructure">Tool Handout: Free infrastructure</a>). Check which version the client speaks; make the server answer <code>tools/list</code> sensibly either way.</li><li><strong>Old tutorials.</strong> Many 2025 tutorials import the legacy SDK. Code that mixes the legacy and current SDKs fails in confusing ways.</li><li><strong>A server you didn&#39;t write won&#39;t start?</strong> Read its startup command before you run it: launching a server is running its code (<a href="./../setup/safety-contract.html#8-read-before-you-adopt">rule 8</a>).</li></ol><h2 id="the-agent-broke-or-deleted-things" tabindex="-1">The agent broke or deleted things <a class="header-anchor" href="#the-agent-broke-or-deleted-things" aria-label="Permalink to &quot;The agent broke or deleted things&quot;">​</a></h2><ol><li><strong>Stop the agent.</strong> Deny the next approval, or interrupt it.</li><li><code>git status</code> and <code>git diff</code> to see what changed. <code>git stash</code> or <code>git restore .</code> to discard uncommitted changes, or <code>git switch</code> back to your last good branch.</li><li>If it committed: <code>git log --oneline -5</code>, then <code>git revert [commit]</code> (safe on shared branches) or reset your own unpushed branch.</li><li>Pushed to the team fork? Your pushed history is the backup. <code>main</code> should be protected; if it isn&#39;t, tell your team today.</li><li>Write down what it did and why your approvals let it through. That&#39;s a threat-model finding (<a href="./../templates/THREAT_MODEL.html">THREAT_MODEL.md template</a>).</li></ol><h2 id="i-committed-a-secret" tabindex="-1">I committed a secret <a class="header-anchor" href="#i-committed-a-secret" aria-label="Permalink to &quot;I committed a secret&quot;">​</a></h2><ol><li><strong>Revoke the key at the provider first.</strong> Deleting the commit doesn&#39;t un-leak it.</li><li>Make a new key; put it only in <code>.env</code> or a Codespaces secret (<a href="./../setup/api-keys.html#if-a-key-leaks">api-keys</a>).</li><li>If the commit was never pushed: amend or rebase it out, and check <code>git log -p</code> for any other copy.</li><li>If it was pushed: tell your team and staff. On a public fork, assume it&#39;s been seen. Cleaning history (with a tool such as <code>git filter-repo</code>) and force-pushing is a team decision, and forks keep the old history anyway: the revocation is what protects you.</li><li>Run the history-aware secret scan your kit or fork uses, to make sure there&#39;s no other copy.</li></ol><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><ol><li>Ask your team, then the class channel, with your three answers (expected, actual, what changed) and the exact error.</li><li>Ask staff in the Lab or office hours. A tool problem that blocks more than one student is a TOOLS.md problem: <a href="https://github.com/Boyu-Zhang-UOI/engineering-software-with-ai/issues/new/choose" target="_blank" rel="noreferrer">open a tool change issue</a>.</li><li>If an AI tool helped you debug, say so in <code>AI_LOG.md</code>, and tag what it told you as <strong>inferred</strong> until you&#39;ve confirmed it.</li></ol>',35)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
